import { NextResponse } from 'next/server';

// Mock user preferences - in a real app this would come from a database
function getCurrentUserPreferences() {
  // Simulate dynamic data that changes on each request
  const timestamp = new Date().toISOString();
  const randomTheme = Math.random() > 0.5 ? 'dark' : 'light';
  const randomNotifications = Math.floor(Math.random() * 100);

  return {
    theme: randomTheme,
    notificationsEnabled: Math.random() > 0.3,
    language: 'en',
    lastUpdated: timestamp,
    unreadCount: randomNotifications,
    settings: {
      autoSave: true,
      compactMode: Math.random() > 0.5
    }
  };
}

export async function GET() {
  try {
    // Fetch fresh data on each request
    const preferences = getCurrentUserPreferences();

    return NextResponse.json({
      success: true,
      data: preferences
    });
  } catch (error) {
    console.error('Error fetching user preferences:', error);
    return NextResponse.json(
      {
        success: false,
        error: 'Failed to fetch user preferences'
      },
      { status: 500 }
    );
  }
}

