// Fetch user preferences with no cache to ensure fresh data on each request
async function fetchUserPreferences() {
  try {
    const res = await fetch(`${process.env.NEXT_PUBLIC_BASE_URL || ''}/api/user/preferences`, {
      // Disable caching to ensure fresh data on each request
      cache: 'no-store',
      // Optional: Add headers if needed for authentication
      headers: {
        'Content-Type': 'application/json',
      },
    });

    if (!res.ok) {
      throw new Error('Failed to fetch user preferences');
    }

    const data = await res.json();
    return data.data;
  } catch (error) {
    console.error('Error fetching user preferences:', error);
    // Return fallback data
    return {
      theme: 'light',
      notificationsEnabled: false,
      language: 'en',
      lastUpdated: new Date().toISOString(),
      unreadCount: 0,
      settings: {
        autoSave: true,
        compactMode: false
      }
    };
  }
}

export default async function UserDashboard() {
  const preferences = await fetchUserPreferences();

  return (
    <div className="user-dashboard">
      <h2>User Dashboard</h2>

      <div className="preferences-section">
        <h3>Your Preferences</h3>
        <div className="preference-item">
          <span className="label">Theme:</span>
          <span className="value">{preferences.theme}</span>
        </div>
        <div className="preference-item">
          <span className="label">Notifications:</span>
          <span className="value">
            {preferences.notificationsEnabled ? 'Enabled' : 'Disabled'}
          </span>
        </div>
        <div className="preference-item">
          <span className="label">Language:</span>
          <span className="value">{preferences.language}</span>
        </div>
        <div className="preference-item">
          <span className="label">Unread Count:</span>
          <span className="value">{preferences.unreadCount}</span>
        </div>
        <div className="preference-item">
          <span className="label">Last Updated:</span>
          <span className="value">
            {new Date(preferences.lastUpdated).toLocaleString()}
          </span>
        </div>

        <div className="settings-section">
          <h4>Settings</h4>
          <div className="setting-item">
            <span className="label">Auto Save:</span>
            <span className="value">
              {preferences.settings.autoSave ? 'On' : 'Off'}
            </span>
          </div>
          <div className="setting-item">
            <span className="label">Compact Mode:</span>
            <span className="value">
              {preferences.settings.compactMode ? 'On' : 'Off'}
            </span>
          </div>
        </div>
      </div>

      <style jsx>{`
        .user-dashboard {
          margin-top: 2rem;
          padding: 2rem;
          border: 1px solid #e5e7eb;
          border-radius: 8px;
          background: #f9fafb;
        }

        h2 {
          color: #111827;
          margin-bottom: 1rem;
        }

        h3 {
          color: #374151;
          margin-bottom: 1rem;
          font-size: 1.1rem;
        }

        h4 {
          color: #6b7280;
          margin: 1.5rem 0 0.5rem 0;
          font-size: 0.9rem;
          text-transform: uppercase;
          letter-spacing: 0.05em;
        }

        .preferences-section {
          background: white;
          padding: 1.5rem;
          border-radius: 6px;
          border: 1px solid #e5e7eb;
        }

        .preference-item, .setting-item {
          display: flex;
          justify-content: space-between;
          align-items: center;
          padding: 0.5rem 0;
          border-bottom: 1px solid #f3f4f6;
        }

        .preference-item:last-child, .setting-item:last-child {
          border-bottom: none;
        }

        .label {
          font-weight: 500;
          color: #374151;
        }

        .value {
          color: #6b7280;
          font-family: monospace;
        }

        .settings-section {
          margin-top: 1.5rem;
          padding-top: 1rem;
          border-top: 1px solid #e5e7eb;
        }
      `}</style>
    </div>
  );
}

